def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove if expired
            if key in cache and is_expired(key, t):
                del cache[key]
            if key in cache:
                # update existing, move to most recently used
                cache.pop(key)
                cache[key] = (value, t)
            else:
                # need to check capacity, first purge expired entries doesn't matter for eviction logic
                if len(cache) >= capacity:
                    # evict least recently used
                    cache.popitem(last=False)
                cache[key] = (value, t)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.pop(key)
                cache[key] = (value, wt)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

